-- Style references an ad can follow. Rows with no workspace are Gooidy's own
-- library (original AI images, generated by an admin); rows with a workspace
-- are references its owners uploaded. Files live in the private "creatives"
-- bucket and are handed out as signed URLs by the server. Additive only.
create table if not exists public.style_references (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade,
  slug text unique,
  category text not null,
  style text,
  storage_path text not null unique,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check ((workspace_id is null) = (slug is not null))
);
create index if not exists style_references_workspace_idx on public.style_references(workspace_id, created_at desc);
alter table public.style_references enable row level security;
revoke all on public.style_references from public, anon, authenticated;
grant select on public.style_references to authenticated;
grant all on public.style_references to service_role;
create policy "read library and own style references" on public.style_references
  for select to authenticated
  using (workspace_id is null or public.is_workspace_member(workspace_id));
